INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was bedeutet Barrierefreiheit im IT-Kontext?', 2, '[{"text": "Zugänglichkeit für alle Nutzer", "correct": true, "because": "Inklusive Menschen mit Behinderungen"}, {"text": "Schnellere Systeme", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Barrierefreiheit als Fachinformatiker?', 3, '[{"text": "Inklusion ermöglichen", "correct": true, "because": "Alle sollen Systeme nutzen können"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Standards gehören zur Barrierefreiheit?', 5, '[{"text": "WCAG", "correct": true, "because": "Web Content Accessibility Guidelines"}, {"text": "ISO 9241", "correct": true, "because": "Ergonomie von Mensch-System-Interaktion"}, {"text": "HTML5", "correct": false, "because": "Technologie, kein Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Barrierefreiheit ist gesetzlich vorgeschrieben. b) Sie gilt nur für Websites.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Apps und Systeme betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Barrierefreiheit?', 4, '[{"text": "Nutzungsanforderungen", "correct": false, "because": "Kern der Planung"}, {"text": "WCAG-Richtlinien", "correct": false, "because": "Grundlage"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Barrierefreiheit Screenreader unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Für Sehbehinderte essenziell"}, {"text": "Nein", "correct": false, "because": "Teil der Anforderungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Barrierefreiheit in Deutschland?', 3, '[{"text": "BITV", "correct": true, "because": "Barrierefreie-Informationstechnik-Verordnung"}, {"text": "ArbZG", "correct": false, "because": "Arbeitszeitgesetz"}, {"text": "MiLoG", "correct": false, "because": "Mindestlohngesetz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Umsetzung von Barrierefreiheit?', 5, '[{"text": "Alternative Texte", "correct": true, "because": "Für Bilder nötig"}, {"text": "Tastaturnavigation", "correct": true, "because": "Für Motorikbehinderte"}, {"text": "Farbliches Design", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Barrierefreiheit verbessert die Nutzerfreundlichkeit. b) Sie ist nur für Behinderte relevant. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nutzen für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Barrierefreiheit unwichtig?', 4, '[{"text": "Kontraste", "correct": false, "because": "Für Sehbehinderte wichtig"}, {"text": "Tastaturbedienung", "correct": false, "because": "Für Motorik essenziell"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss Barrierefreiheit für öffentliche Webseiten gelten?', 2, '[{"text": "Ja", "correct": true, "because": "BITV-Pflicht"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Barrierefreiheit für Fachinformatiker?', 4, '[{"text": "Breitere Nutzerbasis", "correct": true, "because": "Mehr Menschen erreicht"}, {"text": "Rechtliche Konformität", "correct": true, "because": "Vermeidet Sanktionen"}, {"text": "Schnellere Ladezeiten", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Barrierefreiheit die Entwicklung verzögert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Mit Planung effizient"}, {"text": "Ja", "correct": false, "because": "Abhängig von Umsetzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Barrierefreiheit?', 3, '[{"text": "WCAG-Richtlinien", "correct": true, "because": "Standard für Zugänglichkeit"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Barrierefreiheit umfasst Farbenblindheit. b) Sie ist nur für Webentwickler relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Systeme betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat mangelnde Barrierefreiheit?', 5, '[{"text": "Ausschluss von Nutzern", "correct": true, "because": "Behinderte ausgeschlossen"}, {"text": "Rechtliche Konsequenzen", "correct": true, "because": "Verstoß gegen BITV"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Barrierefreiheit?', 3, '[{"text": "WCAG-konforme Entwicklung", "correct": true, "because": "Sicherstellt Zugänglichkeit"}, {"text": "Hardwarewartung", "correct": false, "because": "Kein direkter Bezug"}, {"text": "Marketing", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann Barrierefreiheit in Software getestet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Tools wie Screenreader"}, {"text": "Nein", "correct": false, "because": "Testbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool könnte ein Fachinformatiker für Barrierefreiheit nutzen?', 4, '[{"text": "WAVE", "correct": true, "because": "Testet Web-Barrierefreiheit"}, {"text": "Photoshop", "correct": false, "because": "Design, kein Test"}, {"text": "Excel", "correct": false, "because": "Tabellenkalkulation"}]');
